  const a = await fetch(url);
  const versao = a.headers.get('etag') ?? '';
  console.log(a.status, versao, (await a.text()).length);
  const b = await fetch(url, { headers: { 'if-none-match': versao } });
  console.log(b.status, (await b.text()).length);
  server.close();
});

