    res.setHeader('set-cookie', ['rt=abc; HttpOnly; Path=/auth', 'tema=escuro']);
    res.end('ok');
    return;
  }
  res.end(req.headers.cookie ?? 'sem cookie');
});

server.listen(0, '127.0.0.1', async () => {
