  const base = `http://127.0.0.1:${port}`;
  const login = await fetch(base + '/login');
  console.log(login.headers.getSetCookie());
  console.log(await (await fetch(base + '/eu')).text());
  const comCookie = await fetch(base + '/eu', { headers: { cookie: 'tema=escuro' } });
  console.log(await comCookie.text());
  server.close();
});

import { createServer } from 'node:http';

