const guardadas = new Map<string, { status: number; id: number }>();
let criadas = 0;

function criarTarefa(chave: string) {
  const anterior = guardadas.get(chave);
  if (anterior) return anterior;
  const resposta = { status: 201, id: ++criadas };
  guardadas.set(chave, resposta);
  return resposta;
}

console.log(criarTarefa('clique-A'));
console.log(criarTarefa('clique-A')); // retry
console.log(criarTarefa('clique-B'));
console.log(criadas);

